do $$
declare
  v_course uuid;
  v_module uuid;
begin
  select id into v_course from nexora.courses where title='Lógica de Programação Básica' limit 1;
  select id into v_module from nexora.modules where course_id=v_course and position=4 limit 1;

  update nexora.lessons set estimated_minutes=30,lab_type='logic',lab_config=$json${"module":"Repetições","pedagogy":"estado-iteracao-rastreio-validacao","concept":"Reconhecer quando repetição representa melhor uma tarefa do que duplicação manual.","checkpoint":{"question":"Uma rotina deve processar 80 registros da mesma forma. Qual abordagem representa melhor o problema?","options":["Copiar o mesmo bloco 80 vezes.","Definir a operação uma vez e repeti-la para cada registro.","Criar 80 variáveis com nomes diferentes.","Executar apenas o primeiro registro."],"answer":1,"feedback":"Correto. A repetição expressa uma operação recorrente sem duplicar a regra.","feedback_incorrect":"Procure a alternativa que mantém uma única regra e varia apenas o item processado."},"editorial_version":"lc-content-standard-1.0"}$json$::jsonb,content=$json$[{"type":"problem","title":"Duplicação manual é um sinal de padrão repetido","body":"Imagine validar 80 cadastros. Copiar o mesmo bloco 80 vezes não cria 80 regras diferentes; cria uma única regra duplicada. Laços permitem expressar: aplique esta operação repetidamente enquanto houver trabalho."},{"type":"concept","title":"Repetição combina operação, estado e critério de continuidade","body":"Um laço precisa responder três perguntas: o que acontece em cada iteração, o que muda entre uma iteração e outra e quando a repetição termina."},{"type":"comparison","title":"Repetição não é sinônimo de quantidade fixa","items":["Pode repetir para cada item de uma coleção.","Pode repetir uma quantidade conhecida de vezes.","Pode repetir enquanto uma condição permanecer verdadeira.","Pode encerrar antecipadamente quando um evento ocorre."]},{"type":"case_study","title":"Caso: fila de leads","body":"Uma equipe precisa verificar todos os leads importados e marcar quais têm telefone válido. Identifique o item atual, a operação repetida, o estado que pode ser atualizado e a condição de término."},{"type":"trace","title":"Rastreie três iterações","items":["iteração 1 → lead A → validar → avançar","iteração 2 → lead B → validar → avançar","iteração 3 → lead C → validar → avançar"]},{"type":"transfer","title":"Identifique repetição em outro processo","body":"Escolha um processo cotidiano ou administrativo com tarefas semelhantes. Descreva o que permanece igual e o que muda a cada ciclo. Essa distinção prepara contador, acumulador e percurso de listas."}]$json$::jsonb,updated_at=now() where module_id=v_module and position=1;

  update nexora.lessons set estimated_minutes=32,lab_type='pseudocode',lab_config=$json${"module":"Repetições","pedagogy":"estado-iteracao-rastreio-validacao","concept":"Usar contador para representar quantas ocorrências ou iterações satisfazem um critério.","checkpoint":{"question":"Ao contar quantos pedidos foram aprovados, quando o contador deve aumentar?","options":["Antes de ler qualquer pedido.","Sempre que um pedido satisfizer a condição de aprovação.","Somente no fim da lista.","Somente quando o valor do pedido for zero."],"answer":1,"feedback":"Correto. O contador muda quando ocorre o evento que ele representa.","feedback_incorrect":"Relacione a atualização do contador ao evento que está sendo contado."},"editorial_version":"lc-content-standard-1.0"}$json$::jsonb,content=$json$[{"type":"concept","title":"Contador responde quantas vezes algo aconteceu","body":"Um contador começa com um valor conhecido e é atualizado quando ocorre o evento que queremos contar. `aprovados = aprovados + 1` significa: observamos mais uma ocorrência relevante."},{"type":"worked_example","title":"Conte pedidos aprovados","body":"Comece `aprovados = 0`. Para cada pedido, avalie a regra. Se aprovado, incremente. Ao terminar, o contador representa a quantidade total de aprovações — não o número de itens percorridos, a menos que todos tenham sido aprovados."},{"type":"trace_table","title":"Faça o contador evoluir","items":["pedido A aprovado → 0 → 1","pedido B recusado → 1 → 1","pedido C aprovado → 1 → 2","pedido D aprovado → 2 → 3"]},{"type":"comparison","title":"Índice, iteração e contador podem ser coisas diferentes","body":"O laço pode estar na quarta iteração e o contador de aprovados valer 3. Não use uma variável de posição como se ela representasse automaticamente a métrica do negócio."},{"type":"bug_hunt","title":"Encontre o incremento no lugar errado","body":"Analise um pseudocódigo que incrementa `aprovados` fora do SE. Mostre por que pedidos recusados passam a ser contados e reposicione a atualização no ramo correto."},{"type":"practice","title":"Conte ocorrências condicionais","body":"Crie um algoritmo para contar notas >= 7 em uma lista. Faça teste de mesa com [8, 5, 7, 4, 10] e registre o contador após cada elemento."},{"type":"professional_context","title":"Contadores viram indicadores","body":"Quantidade de erros, vendas, aprovações, tentativas e itens processados são contadores comuns em software e analytics. A definição do evento contado precisa ser explícita."}]$json$::jsonb,updated_at=now() where module_id=v_module and position=2;

  update nexora.lessons set estimated_minutes=32,lab_type='pseudocode',lab_config=$json${"module":"Repetições","pedagogy":"estado-iteracao-rastreio-validacao","concept":"Usar acumulador para combinar valores progressivamente durante uma repetição.","checkpoint":{"question":"Para calcular a receita total de vendas, qual atualização caracteriza um acumulador?","options":["receita = receita + valorVenda","receita = receita + 1","receita = 0 a cada venda","receita = quantidadeVendas"],"answer":0,"feedback":"Correto. O acumulador incorpora o valor atual ao total anterior.","feedback_incorrect":"Procure a operação que preserva o total anterior e acrescenta o valor da iteração atual."},"editorial_version":"lc-content-standard-1.0"}$json$::jsonb,content=$json$[{"type":"problem","title":"Contar vendas não calcula receita","body":"Cinco vendas podem gerar R$ 500 ou R$ 50 mil. Quando queremos combinar valores, precisamos de um acumulador, não de um contador."},{"type":"concept","title":"Acumulador carrega um resultado parcial","body":"`total = total + valorAtual` combina o resultado anterior com o dado da iteração. O valor inicial depende da operação: para soma, normalmente 0; para outros agregados, a identidade pode ser diferente."},{"type":"trace_table","title":"Rastreie o total parcial","items":["início → 0","+ 120 → 120","+ 80 → 200","+ 300 → 500"]},{"type":"comparison","title":"Contador × acumulador","items":["contador adiciona uma unidade por ocorrência","acumulador incorpora um valor da iteração","contador responde quantos","acumulador pode responder quanto, soma ou resultado agregado"]},{"type":"error_analysis","title":"Reinicializar dentro do laço apaga o passado","body":"Se `total = 0` estiver dentro da repetição, cada iteração descarta o resultado anterior. A inicialização deve ocorrer antes do percurso quando o objetivo é agregar toda a coleção."},{"type":"practice","title":"Some somente valores válidos","body":"Dada a lista [100, -20, 80, 0, 50], considere válidas apenas vendas maiores que zero. Rastreie item atual, condição e total acumulado. Resultado esperado: 230."},{"type":"transfer","title":"Além de soma","body":"Média costuma combinar contador e acumulador: soma dos valores / quantidade de valores válidos. Reconhecer esses papéis prepara algoritmos de relatório e análise de dados."}]$json$::jsonb,updated_at=now() where module_id=v_module and position=3;

  update nexora.lessons set estimated_minutes=34,lab_type='pseudocode',lab_config=$json${"module":"Repetições","pedagogy":"estado-iteracao-rastreio-validacao","concept":"Usar PARA quando a sequência ou coleção a percorrer está claramente definida.","checkpoint":{"question":"Qual cenário combina naturalmente com PARA?","options":["Tentar login até a senha ser válida.","Processar cada item de uma lista de pedidos.","Esperar até o estoque mudar.","Repetir enquanto o usuário não encerrar."],"answer":1,"feedback":"Correto. PARA é natural quando a coleção ou sequência é conhecida.","feedback_incorrect":"Procure o caso em que os elementos a percorrer já estão definidos."},"editorial_version":"lc-content-standard-1.0"}$json$::jsonb,content=$json$[{"type":"scenario","title":"Quando sabemos o conjunto a percorrer","body":"Se uma lista possui pedidos e a regra é processar cada um, o PARA comunica diretamente a intenção: para cada pedido, execute a operação."},{"type":"concept","title":"PARA controla uma progressão definida","body":"A sequência pode ser numérica ou uma coleção. O importante é que o algoritmo sabe como obter o próximo elemento e quando o percurso termina."},{"type":"worked_example","title":"De 1 até 5","body":"Rastreie `i` assumindo uma sequência inclusiva: 1, 2, 3, 4, 5. Antes de programar, declare se o limite final participa da sequência; linguagens diferentes podem representar intervalos de modo diferente."},{"type":"off_by_one","title":"O bug de uma iteração a mais ou a menos","body":"Erros de início e fim aparecem quando o desenvolvedor assume uma fronteira diferente da biblioteca ou linguagem. Sempre teste primeiro elemento, último elemento e tamanho da coleção."},{"type":"practice","title":"Percorra uma semana de metas","body":"Para os valores [10, 12, 9, 15, 14], escreva pseudocódigo que exiba cada valor e conte quantos atingiram meta >= 12. Faça o teste de mesa."},{"type":"comparison","title":"PARA comunica intenção melhor que um ENQUANTO manual quando a sequência já existe","body":"Ambos podem produzir o mesmo resultado, mas PARA reduz estado de controle explícito quando o percurso já é conhecido."},{"type":"professional_context","title":"Percursos dominam processamento de dados","body":"Importações, relatórios, listas de usuários e resultados de APIs são frequentemente processados com a ideia 'para cada registro'."}]$json$::jsonb,updated_at=now() where module_id=v_module and position=4;

  update nexora.lessons set estimated_minutes=38,lab_type='decision_table',lab_config=$json${"module":"Repetições","pedagogy":"estado-iteracao-rastreio-validacao","checkpoint":{"question":"Qual requisito combina melhor com ENQUANTO?","options":["Processar exatamente os 5 dias úteis.","Repetir tentativas enquanto a entrada permanecer inválida.","Percorrer uma lista de 10 produtos conhecida.","Somar três notas fixas."],"answer":1,"feedback":"Correto. A quantidade de repetições depende de uma condição que muda durante a execução.","feedback_incorrect":"Procure o cenário em que não sabemos previamente quantas iterações serão necessárias."},"decision_table":{"title":"Decision Table — condição de continuidade","scenario":"Permitir até 3 tentativas enquanto a senha estiver inválida.","outcomes":["Continuar","Encerrar: sucesso","Encerrar: limite"],"rows":[{"case":"inválida, tentativas=1","answer":0},{"case":"válida, tentativas=1","answer":1},{"case":"inválida, tentativas=2","answer":0},{"case":"inválida, tentativas=3","answer":2}],"feedback":"Você distinguiu continuidade, sucesso e limite de segurança.","feedback_incorrect":"Observe simultaneamente validade e número de tentativas."},"editorial_version":"lc-content-standard-1.0"}$json$::jsonb,content=$json$[{"type":"incident","title":"Um ENQUANTO sem mudança pode nunca terminar","body":"Se a condição depende de `tentativas < 3` e `tentativas` nunca é atualizada, o laço pode permanecer verdadeiro indefinidamente. A condição de continuidade precisa estar conectada a algum estado que evolui."},{"type":"concept","title":"ENQUANTO é adequado quando a quantidade de ciclos emerge da execução","body":"Repita enquanto a condição for verdadeira. Em geral, inicialização, teste da condição e atualização do estado precisam formar um ciclo coerente."},{"type":"state_machine","title":"Veja a evolução do estado","items":["inicializar tentativas=0","testar senha e limite","processar tentativa","atualizar tentativas ou validade","voltar à condição"]},{"type":"safety","title":"Defina uma saída de segurança","body":"Quando a condição depende de entrada externa ou evento, considere timeout, limite de tentativas ou cancelamento. Laços de produção precisam de uma estratégia de término previsível."},{"type":"bug_hunt","title":"Encontre o laço infinito","body":"Analise: `enquanto saldo > 0: mostrar saldo`. O saldo nunca muda. Proponha uma atualização ou condição diferente e explique qual evento encerra a repetição."},{"type":"practice","title":"Modele tentativas de autenticação","body":"Crie o estado para permitir no máximo 3 tentativas e encerrar imediatamente em caso de sucesso. Liste os estados após cada tentativa para os cenários: erro, erro, sucesso; e erro, erro, erro."},{"type":"professional_context","title":"Polling, retry e processamento usam condições de continuidade","body":"Repetir até sucesso, timeout ou limite é comum em integrações. Sem política explícita de término, um pequeno erro lógico pode consumir recursos indefinidamente."}]$json$::jsonb,updated_at=now() where module_id=v_module and position=5;

  update nexora.lessons set estimated_minutes=36,lab_type='data_model',lab_config=$json${"module":"Repetições","pedagogy":"estado-iteracao-rastreio-validacao","checkpoint":{"question":"Ao percorrer uma lista, o que representa o item atual?","options":["A coleção inteira.","Um elemento da coleção naquela iteração.","Sempre o primeiro elemento.","O tamanho da lista."],"answer":1,"feedback":"Correto. Cada iteração trabalha com um elemento do percurso.","feedback_incorrect":"Separe a coleção completa do elemento selecionado na iteração atual."},"data_model":{"scenario":"Classifique o papel de cada elemento ao calcular a média das notas [8, 6, 10].","options":["Coleção","Item atual","Acumulador","Contador"],"rows":[{"label":"notas","value":"[8, 6, 10]","answer":0},{"label":"nota","value":"6","answer":1},{"label":"soma","value":"14","answer":2},{"label":"quantidade","value":"2","answer":3}],"feedback":"Correto. Você separou coleção, elemento e estados agregados.","feedback_incorrect":"Pergunte se o elemento contém todos os dados, apenas o registro atual, uma soma parcial ou uma contagem."},"editorial_version":"lc-content-standard-1.0"}$json$::jsonb,content=$json$[{"type":"concept","title":"Percorrer uma lista separa coleção e elemento atual","body":"A coleção contém todos os valores; em cada iteração, uma variável representa apenas o elemento corrente. Essa distinção é central para filtrar, transformar e agregar dados."},{"type":"worked_example","title":"Média de notas","body":"Para [8, 6, 10], percorra cada nota, some ao acumulador e conte quantos valores participaram. Ao final: soma=24, quantidade=3, média=8."},{"type":"trace_table","title":"Estado por iteração","items":["8 → soma 8 → quantidade 1","6 → soma 14 → quantidade 2","10 → soma 24 → quantidade 3"]},{"type":"edge_case","title":"Lista vazia é um estado válido","body":"Dividir soma por quantidade quando a lista está vazia produz problema. Antes de calcular média, defina o comportamento esperado para zero elementos."},{"type":"practice","title":"Percorra e filtre","body":"Na lista [5, 8, 3, 10, 7], some apenas valores >= 7 e conte quantos participaram. Registre item, condição, soma e contador em cada iteração."},{"type":"comparison","title":"Não altere a coleção sem entender o efeito do percurso","body":"Remover itens da mesma lista enquanto ela é percorrida pode pular elementos ou invalidar índices. Quando necessário, filtre para uma nova coleção ou use estratégia segura da linguagem."},{"type":"professional_context","title":"Listas conectam lógica a dados reais","body":"Resultados de API, linhas de planilha, pedidos e alunos chegam como coleções. Percorrê-las com estado explícito é uma competência central de automação e análise."}]$json$::jsonb,updated_at=now() where module_id=v_module and position=6;

  update nexora.lessons set estimated_minutes=44,lab_type='decision_table',lab_config=$json${"module":"Repetições","pedagogy":"estado-iteracao-rastreio-validacao","checkpoint":{"question":"Ao somar apenas vendas aprovadas, qual estrutura representa a intenção?","options":["Somar todas e corrigir no fim.","Para cada venda, testar se está aprovada e então acumular seu valor.","Alterar a lista enquanto percorre.","Usar apenas o índice como total."],"answer":1,"feedback":"Correto. O laço percorre e a condição decide quais itens participam do acumulador.","feedback_incorrect":"Separe o papel do percurso, do filtro e da agregação."},"decision_table":{"title":"Decision Table — percurso com filtro","scenario":"Some somente vendas com status aprovado.","outcomes":["Acumular","Ignorar"],"rows":[{"case":"R$ 100, aprovado","answer":0},{"case":"R$ 80, cancelado","answer":1},{"case":"R$ 50, aprovado","answer":0},{"case":"R$ 200, pendente","answer":1}],"feedback":"Filtro correto. Apenas registros aprovados participam do total.","feedback_incorrect":"O status é a condição que decide se o valor entra no acumulador."},"editorial_version":"lc-content-standard-1.0"}$json$::jsonb,content=$json$[{"type":"capstone","title":"Percorrer, decidir e agregar","body":"Problemas reais combinam estruturas: o laço encontra cada registro, a condição decide se ele participa e contador/acumulador registram o resultado."},{"type":"decomposition","title":"Separe os três papéis","items":["Percurso: obter cada venda.","Filtro: status é aprovado?","Agregação: somar valor e contar aprovação."]},{"type":"worked_example","title":"Relatório de vendas aprovadas","body":"[100 aprovado, 80 cancelado, 50 aprovado] → total aprovado 150 e quantidade aprovada 2. O registro cancelado é percorrido, mas não altera os agregados."},{"type":"trace_matrix","title":"Prove o estado a cada registro","items":["100 aprovado → total 100, qtd 1","80 cancelado → total 100, qtd 1","50 aprovado → total 150, qtd 2"]},{"type":"error_analysis","title":"Filtrar depois de somar pode complicar a correção","body":"Quando a regra permite decidir no momento do percurso, manter registros inválidos fora da agregação reduz a necessidade de desfazer cálculos e torna o raciocínio mais local."},{"type":"performance_reasoning","title":"Uma passagem bem desenhada pode resolver várias métricas relacionadas","body":"Contar aprovados e somar valores aprovados compartilham o mesmo filtro. É possível atualizar os dois agregados na mesma iteração sem duplicar o percurso, desde que cada estado tenha responsabilidade clara."},{"type":"practice","title":"Construa um relatório pequeno","body":"Dada uma lista de atendimentos com status e tempo em minutos, calcule quantidade concluída e tempo total apenas dos concluídos. Inclua lista vazia, um item pendente e pelo menos dois concluídos."},{"type":"mastery","title":"Critério de domínio de repetições","items":["Escolho entre PARA e ENQUANTO pela natureza do percurso.","Separo item atual de coleção.","Rastreio contador e acumulador.","Defino condição de término.","Considero lista vazia e limites.","Combino laço e condição sem perder clareza."]}]$json$::jsonb,updated_at=now() where module_id=v_module and position=7;

  update nexora.assessments set title='Checkpoint aplicado — Repetições, estado e percurso', max_attempts=3 where course_id=v_course and module_id=v_module;

  insert into nexora.learning_resources(course_id,module_id,title,resource_type,summary,content,position,status)
  select v_course,v_module,'Planilha mental — Rastreio de laços','template','Template de teste de mesa para acompanhar iteração, item atual, condição, contador, acumulador e estado de término.',$json${"sections":[{"title":"Colunas de rastreio","items":["Iteração","Item atual","Condição","Contador antes/depois","Acumulador antes/depois","Estado de saída"]},{"title":"Casos obrigatórios","items":["Primeira iteração","Última iteração","Coleção vazia","Item que não satisfaz o filtro","Caso que encerra um ENQUANTO"]},{"title":"Perguntas de revisão","items":["O estado muda em toda iteração necessária?","Existe risco de laço infinito?","Inicialização está fora do laço quando deve preservar histórico?","O limite final é inclusivo ou exclusivo?"]}],"editorial_version":"lc-content-standard-1.0"}$json$::jsonb,5,'published'
  where not exists(select 1 from nexora.learning_resources where module_id=v_module and title='Planilha mental — Rastreio de laços');
end $$;
